//! ↩️ reorder-materials leaf-owned inverse reconstruction from exact base values.
use serde::{Deserialize, Serialize};
use crate::artifacts::gltf::GltfSnapshot;
use crate::artifacts::gltf::schema::snapshot::GltfMaterial;
use crate::artifacts::gltf::schema::mutations::reorder_materials::mutation::{validate, GltfReorderMaterialsPayload};
use crate::artifacts::gltf::schema::mutations::top_level_collections_private::{materials_op, reject, repair, Change, GltfTopLevelFamily, GltfTopLevelMutationRejection};
pub const ID: &str = "s.stdio.gltf.mutation.reorder-materials.v1.inverse";
#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)] #[serde(tag = "kind", rename_all = "camelCase")]
pub enum GltfReorderMaterialsInverseOperation { Insert { position: usize, item: GltfMaterial }, Delete { index: usize, removed: GltfMaterial }, Move { index: usize, position: usize }, Reorder { order: Vec<usize> } }
#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)] #[serde(rename_all = "camelCase")]
pub struct GltfReorderMaterialsInverse { pub id: String, pub version: u32, pub touched_paths: Vec<String>, pub payload: GltfReorderMaterialsPayload, pub operation: GltfReorderMaterialsInverseOperation }
fn operation(payload: &GltfReorderMaterialsPayload, base: &GltfSnapshot) -> GltfReorderMaterialsInverseOperation { GltfReorderMaterialsInverseOperation::Reorder { order: (0..payload.order.len()).map(|index| payload.order.iter().position(|value| *value == index).unwrap()).collect() } }
fn touched_paths(payload: &GltfReorderMaterialsPayload) -> Vec<String> { payload.order.iter().map(|index| format!("document/materials/{}", index)).chain(std::iter::empty()).collect() }
pub fn validate_inverse(inverse: &GltfReorderMaterialsInverse) -> Result<(), GltfTopLevelMutationRejection> { if inverse.id != ID || inverse.version != 1 { return Err(reject("gltf.mutation.invalid-inverse-envelope", "inverse", "descriptor identity does not match")); } if inverse.touched_paths != touched_paths(&inverse.payload) { return Err(reject("gltf.mutation.invalid-touched-paths", "inverse/touchedPaths", "paths must be concrete payload-derived locations")); } Ok(()) }
pub fn apply_inverse(inverse: &GltfReorderMaterialsInverse, after: &GltfSnapshot) -> Result<GltfSnapshot, GltfTopLevelMutationRejection> { validate_inverse(inverse)?; let operation = &inverse.operation; match operation { GltfReorderMaterialsInverseOperation::Insert { position, .. } if *position > after.document.materials.len() => return Err(reject("gltf.mutation.insert-out-of-range", "document/materials", "position must be within the collection")), GltfReorderMaterialsInverseOperation::Delete { index, .. } if *index >= after.document.materials.len() => return Err(reject("gltf.mutation.index-out-of-range", "document/materials", "index must address an item")), GltfReorderMaterialsInverseOperation::Move { index, position } if *index >= after.document.materials.len() || *position >= after.document.materials.len() => return Err(reject("gltf.mutation.index-out-of-range", "document/materials", "indices must address items")), GltfReorderMaterialsInverseOperation::Reorder { order } if order.is_empty() || order.len() != after.document.materials.len() || order.iter().collect::<std::collections::BTreeSet<_>>().len() != order.len() || order.iter().any(|index| *index >= after.document.materials.len()) => return Err(reject("gltf.mutation.invalid-permutation", "document/materials", "order must be a non-empty permutation")), _ => {} } let mut next = after.clone(); match operation { GltfReorderMaterialsInverseOperation::Insert { position, item } => { repair(&mut next.document, GltfTopLevelFamily::Materials, &Change::Insert(*position))?; next.document.materials.insert(*position, item.clone());  }, GltfReorderMaterialsInverseOperation::Delete { index, .. } => { materials_op(&mut next, GltfTopLevelFamily::Materials, *index, None, None)?;  }, GltfReorderMaterialsInverseOperation::Move { index, position } => { materials_op(&mut next, GltfTopLevelFamily::Materials, *index, Some(*position), None)?;  }, GltfReorderMaterialsInverseOperation::Reorder { order } => { materials_op(&mut next, GltfTopLevelFamily::Materials, order[0], None, Some(order))?;  } } Ok(next) }
pub fn encode(inverse: &GltfReorderMaterialsInverse) -> Result<Vec<u8>, GltfTopLevelMutationRejection> { serde_json::to_vec(inverse).map_err(|error| reject("gltf.mutation.encode-failed", "inverse", error.to_string())) }
pub fn derive(payload: &GltfReorderMaterialsPayload, base: &GltfSnapshot) -> Result<GltfReorderMaterialsInverse, GltfTopLevelMutationRejection> { validate(payload, base)?; Ok(GltfReorderMaterialsInverse { id: ID.into(), version: 1, touched_paths: touched_paths(payload), payload: payload.clone(), operation: operation(payload, base) }) }
